mapper.select:
SELECT (SELECT GROUP_CONCAT(so_code SEPARATOR ', ') FROM sales_orders WHERE id IN (SELECT sales_order_id FROM delivery_details WHERE delivery_id = deliveries.id)) AS invoiceCode,
ORDER BY deliveries.id DESC
LIMIT #{filter.page}, #{filter.rowsPerPage}

mapper.update:
UPDATE deliveries SET
    status = #{status},
    modified = NOW(),
    modified_by = #{userId}
WHERE id = #{id}

UPDATE deliveries SET
    is_approve = 1,
    approved = NOW(),
    approved_by = #{userId}
WHERE id = #{id}
